calls.raw_response:
{
  "schema_version": "0.2",
  "grammar": "counted_grid",
  "tradition_id": "ga_kunbi-check-sari",
  "title": "Kunbi Check Tile",
  "tile": {"width": 64, "height": 64, "wrap_x": true, "wrap_y": true},
  "palette": ["#B0282E", "#F3EEE3", "#1E1E1E", "#2F4A7A"],
  "background_index": 1,
  "layers": [
    {
      "id": "checks",
      "colour_index": 0,
      "anchor": [0, 0],
      "motifs": [
        {"kind": "rectangle", "center": [x*8+4, y*8+4], "size": [8, 8]}
        for x in range(8) for y in range(8) if (x + y) % 2 == 0
      ]
    },
    {
      "id": "pinstripes",
      "colour_index": 2,
      "anchor": [0, 0],
      "motifs": [
        {"kind": "rectangle", "center": [c, 32], "size": [4, 64]}
        for c in [2, 13, 18, 29, 34, 45, 50, 61]
      ]
    },
    {
      "id": "dobby",
      "colour_index": 3,
      "anchor": [0, 0],
      "motifs": [
        {"kind": "rectangle", "center": [x*16+8, 8], "size": [8, 16]}
        for x in range(4)
      ] + [
        {"kind": "rectangle", "center": [x*16+8, 56], "size": [8, 16]}
        for x in range(4)
      ]
    }
  ],
  "constraints": {"cell_size": 4}
}

